// Normaliza o payload do sítio e valida a mensagem.
const body = $input.first().json.body ?? $input.first().json;

const sessionId = String(body.sessionId ?? '').trim();
const message   = String(body.message ?? '').trim().slice(0, 1000);
const lang      = ['pt', 'en', 'kea'].includes(body.lang) ? body.lang : 'pt';
const page      = String(body.page ?? '/').slice(0, 200);
const timestamp = body.timestamp ?? new Date().toISOString();

if (!message) {
  return [{ json: { valido: false, motivo: 'mensagem_vazia', lang } }];
}
if (!sessionId) {
  return [{ json: { valido: false, motivo: 'sessao_em_falta', lang } }];
}

// Detecção simples de pedido de atendimento humano (PT / EN / Kriolu)
const humano = /\[PEDIDO DE ATENDIMENTO HUMANO\]|(falar|fala|conversar|contactar).{0,25}(funcion|pessoa|human|atendente|algu[eé]m|algen|t[ée]cnic|respons[áa]vel)|atendimento (humano|presencial)|(talk|speak|chat)\s+(to|with)\s+(a\s+|an\s+|the\s+)?(member of staff|staff|someone|somebody|human|person|agent|operator|real person|employee)|(human|live)\s+(agent|support|assistance|help|operator|being)|customer (service|support)|(papia|papi[áa]|fal[áa])\s+ku\s+(un\s+)?(algen|pessoa|funcionari)/i.test(message);

// O widget do sítio recolhe nome, email, telefone e assunto num formulário e
// envia-os etiquetados, um por linha. Ler por rótulo é determinístico — sem
// isto o email chegava ao Balcão com «não indicado» em todos os campos.
const linha = (rotulo) => (message.match(new RegExp('^' + rotulo + ':[ \\t]*(.+)$', 'm')) || [])[1]?.trim() || '';
const dados = {
  nome:     linha('Nome'),
  email:    linha('Email'),
  telefone: linha('Telefone'),
  assunto:  linha('Assunto')
};
dados.completo = Boolean(dados.nome && dados.email && dados.telefone && dados.assunto);

return [{ json: { valido: true, sessionId, message, lang, page, timestamp, humano, dados } }];

